from pathlib import Path
import json,gzip,hashlib,datetime,subprocess,collections,difflib,csv
root=Path.cwd();out=root/'00_nucleo/diagnosticos/clippy-expressions-2026-10-16';sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();b=json.load(gzip.open(out/'before.json.gz'));v=json.loads((out/'validation-details.json').read_text());r=json.loads((out/'validation-result.json').read_text());t=json.loads((out/'workspace/workspace-result.json').read_text())
assert len(v['commands'])==9 and all(c['exit']==0 for c in v['commands']) and r['exit']==t['exit']==0
assert v['sources_unchanged_during_validation'] and t['sources_unchanged'] and all(sha(p)==h for p,h in v['source_hashes'].items())
assert v['clippy_total']==94 and sum(v['clippy_delta'].values())==-25
inv=json.loads((out/'clippy-inventory.json').read_text());counts=collections.Counter(c['code'] for c in inv);assert all(counts[k]==0 for k in b['rules']) and counts['clippy::field_reassign_with_default']==counts['clippy::type_complexity']==0
assert r['memory_after']['memory.max'].strip()=='12884901888' and r['memory_after']['memory.swap.max'].strip()=='0' and r['cargo_jobs']=='1'
events={k:int(n) for k,n in (l.split() for l in r['memory_after']['memory.events'].splitlines())};assert events['oom']==events['oom_kill']==0
api=json.loads((out/'public-api-guard.json').read_text());assert all(c['signatures_unchanged'] for c in api['files'])
red=json.loads((out/'observer-red-result.json').read_text());green=json.loads((out/'observer-green-result.json').read_text());assert red['exit']==101 and green['exit']==0
assert '2 passed; 0 failed' in (out/'observer-green.log').read_text()
cases=[]
for c in b['cases']:
 old=b['files'][c['path']]['text'].splitlines();new=Path(c['path']).read_text().splitlines();idx=c['line']-1
 for tag,i1,i2,j1,j2 in difflib.SequenceMatcher(a=old,b=new,autojunk=False).get_opcodes():
  if i1<=idx<i2:line=j1+1+(idx-i1 if tag=='equal' else 0);break
 cases.append(dict(id=c['id'],rule=c['rule'],path=c['path'],before_line=c['line'],after_line=line,owner=c['owner'],status='corrigido',scope='produção equivalente' if c['id'] in ['E001','E002','E003','E004','E005','E008'] else 'testes/observadores'))
assert len(cases)==25
(out/'cases.json').write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
with (out/'cases.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(cases[0]));w.writeheader();w.writerows(cases)
rows=['| Caso | Regra | Fonte atual | L0 |','|---|---|---|---|']+[f"| {c['id']} | `{c['rule']}` | [{c['path']}:{c['after_line']}]({root/c['path']}:{c['after_line']}) | [{c['owner']}]({root/c['owner']}) |" for c in cases]
(out/'lista.md').write_text('# Expressões Clippy — 25 correções\n\nSem novas supressões. O relatório e os snapshots registram proveniência, escopo e a correção funcional adicional do observador PDF.\n\n'+'\n'.join(rows)+'\n')
(out/'stage.diff').write_text(''.join(''.join(difflib.unified_diff(x['text'].splitlines(True),Path(p).read_text().splitlines(True),fromfile='before/'+p,tofile='after/'+p)) for p,x in b['files'].items()))
(out/'remaining-clippy-rules.json').write_text(json.dumps(dict(sorted(counts.items())),indent=2)+'\n')
html={}
for crate in ['typst_core','typst_shell','typst_infra','typst']:
 p=root/'target/doc'/crate/'index.html'
 with p.open() as f:assert '<html' in f.read(300).lower()
 html[str(p.relative_to(root))]=sha(p)
state=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),working_tree='não commitado',source_hashes=v['source_hashes'],sources_unchanged_since_validation=True,documentation_indices=html,status=subprocess.check_output(['git','status','--porcelain=v1','--untracked-files=all'],text=True),diffstat=subprocess.check_output(['git','diff','HEAD','--stat'],text=True));assert state['head']==b['head']
(out/'final-state.json').write_text(json.dumps(state,ensure_ascii=False,indent=2)+'\n')
link=lambda title,name:f'[{title}]({out/name})';peak=int(r['memory_after']['memory.peak'])/1024**3
report=f'''# Expressões Clippy e observador PDF — etapa concluída\n\nForam corrigidos **25 avisos em 17 regras e 16 consumers**, com 16 L0 atualizados antes do código e resselo restrito. O inventário Clippy passou de **119 para 94 avisos**, sem avisos novos de outras regras e sem novas supressões. São seis ocorrências de representação produtiva equivalente e 19 de testes/observadores. Os gates anteriores de type_complexity e field_reassign_with_default continuam em zero.\n\n## Mudanças\n\nif let e Option::map conservam cutoff/fallback da compressão e seleção de páginas/outlines; repeat_n conserva bytes de indentação HTML. O handle de métricas usa cloned sem antecipar o fallback. O envelope Styled reutiliza a Box externa, com o mesmo clone do corpo e estilos. Watch conserva a seleção abandon/abandon_directory após falha.\n\nOs helpers privados aceitam Path/slice onde não precisam de ownership; o controle SVG continua comparando as quatro coordenadas, sem zip truncante. Recortes de XML mantêm fronteiras UTF-8 vindas de tags ASCII; ? permanece depois do registro de sucesso/falha. Regex de labels é compilada uma vez por observação com padrões/defaults idênticos. Observadores de Tc, catálogo não vazio, Glyph, lifetime e RGBA conservam os mesmos dados e expectativas.\n\nA auditoria encontrou uma falha funcional adicional no observador parse_pdf_objects: o ramo `<` tornava o ramo `<<` inalcançável, e EOF com depth positivo ainda publicava corpo parcial. Duas regressões independentes falharam antes da implementação: corpo conhecido com dicionários aninhados, literal/escape, campo após o filho e segundo objeto; e rejeição explícita de entrada truncada. O helper agora reconhece `<<` antes de hex e exige fechamento completo. Não foi criado um parser PDF geral, nem alterado o exportador ou os esperados antigos de outlines. Ambas as regressões passaram depois.\n\n{link('Lista individual','lista.md')} · {link('CSV','cases.csv')} · {link('JSON','cases.json')} · {link('Diff exclusivo da etapa','stage.diff')} · {link('Controle das assinaturas públicas','public-api-guard.json')}. As {api['public_functions']} assinaturas públicas extraídas dos arquivos afetados permaneceram iguais; mudanças de assinatura atingem somente três helpers privados de testes e elisão equivalente do helper de geometria. Nenhuma API, dependência, default do produto ou fase nova foi introduzida.\n\n## Validação\n\nGates dos lints e das duas regressões passaram RED→GREEN. Suíte workspace: **{t['passed']} aprovados, {t['failed']} falhas e {t['ignored']} ignorados**. Os dois novos testes verificam o defeito real do observador; não espelham a sintaxe das simplificações. Não foram relaxadas fixtures, tolerâncias ou expectativas de linguagem existentes.\n\nBuild, Clippy all-targets, formato, Rustdoc com `RUSTDOCFLAGS="-D warnings"`, git diff --check e linhagens estrita V1/V5/V15/V26 e reversa passaram. O Tekt registrou {v['architecture_levels']}, com avisos {v['architecture_warnings']}; sem erros ou avisos arquiteturais novos. As fontes/L0 ficaram imutáveis durante a execução. Os quatro índices HTML foram conferidos após a suíte. {link('Recibo detalhado','validation-details.json')}, {link('resultado dos testes','workspace/workspace-result.json')}, {link('RED do observador','observer-red-result.json')} e {link('GREEN do observador','observer-green-result.json')}.\n\n## RAM, proveniência e pendências\n\nServiços com **MemoryMax=12 GiB, swap zero e CARGO_BUILD_JOBS=1**. Pico da validação: **{peak:.3f} GiB**, incluindo cache de arquivos; eventos max={events['max']}, OOM={events['oom']}, OOM-kill={events['oom_kill']}. O limite cobre os processos dos serviços, não outros aplicativos. {link('Recibo de memória','validation-result.json')}.\n\nHEAD `{b['head']}`, working tree não commitado. Snapshot de origem `{b['utc']}`; validação entre `{v['start']}` e `{v['end']}` UTC. {link('Snapshot anterior','before.json.gz')} e {link('conferência final','final-state.json')} conservam fontes/L0, hashes, lista exata de alterações (`git diff HEAD --stat`), arquivos não rastreados e horários. O linter foi reconstruído offline do mesmo pin do CI, `49c6bb0e584104a0c89270431d8402f5c6c61150`; {link('proveniência do linter','linter-provenance.json')} contém árvore, receita e SHA-256 do binário. A suíte verifica o vanilla pinado `9f2b6e8715237cb086899a42873660fe744622e8`, binário SHA-256 `7fa91e57df43593beef70967898d776d69c8f593b1f324ccb552290821c171ea`. Scripts duráveis em workers/. {link('Manifesto SHA-256','manifest.sha256')}.\n\nRestam 94 avisos Clippy e a dívida de Tekt. Os três Default já foram aprovados em pacote próprio, ainda não materializados neste fechamento. Os 57 casos de too_many_arguments permanecem na auditoria anterior. A meta geral de todas as correções continua aberta. Sem commit, push ou release.\n'''
(out/'relatorio.md').write_text(report)
(out/'manifest.sha256').write_text('\n'.join(f'{sha(p)}  {p.relative_to(out)}' for p in sorted(out.rglob('*')) if p.is_file() and p.name!='manifest.sha256')+'\n')
print(json.dumps(dict(report=str(out/'relatorio.md'),clippy=94,tests=t['passed'],memory_peak_gib=peak),ensure_ascii=False))
